sap.ui.require([
  "sap/m/Table", "sap/m/Column", "sap/m/ColumnListItem", "sap/m/Text",
  "sap/ui/model/json/JSONModel"
], function (Table, Column, ColumnListItem, Text, JSONModel) {
  var oModel = new JSONModel({
    products: [
      { name: "노트북", price: 1200 },
      { name: "모니터", price: 300 },
      { name: "키보드", price: 50 }
    ]
  });

  var oTable = new Table({
    columns: [
      new Column({ header: new Text({ text: "상품명" }) }),
      new Column({ header: new Text({ text: "가격" }), hAlign: "End" })
    ]
  });

  oTable.bindItems({
    path: "/products",
    template: new ColumnListItem({
      cells: [ new Text({ text: "{name}" }), new Text({ text: "{price}" }) ]
    })
  });

  oTable.setModel(oModel);
  oTable.placeAt("content");
});

sap.ui.require([
  "sap/m/Table", "sap/m/Column", "sap/m/ColumnListItem", "sap/m/Text",
  "sap/ui/model/json/JSONModel"
], function (Table, Column, ColumnListItem, Text, JSONModel) {
  var oTable = new Table({
    autoPopinMode: true,
    mode: "SingleSelectMaster",           // sap.m.ListBase 에서 상속
    columns: [
      new Column({ header: new Text({ text: "이름" }), importance: "High" }),
      new Column({ header: new Text({ text: "부서" }), importance: "Medium" }),
      new Column({ header: new Text({ text: "메모" }), importance: "Low" })
    ]
  });

  oTable.bindItems({
    path: "/rows",
    template: new ColumnListItem({
      cells: [
        new Text({ text: "{name}" }),
        new Text({ text: "{dept}" }),
        new Text({ text: "{memo}" })
      ]
    })
  });
  oTable.setModel(new JSONModel({ rows: [
    { name: "김하나", dept: "인사", memo: "-" },
    { name: "이두리", dept: "개발", memo: "원격" }
  ] }));

  oTable.attachSelectionChange(function (oEvent) {   // 상속받은 이벤트
    var oItem = oEvent.getParameter("listItem");
    console.log("선택:", oItem.getBindingContext().getProperty("name"));
  });

  oTable.placeAt("content");
});
